from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix_steps(n: int) -> int:
            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        ans = 0
        for l, r in queries:
            total_steps = prefix_steps(r) - prefix_steps(l - 1)
            ans += (total_steps + 1) // 2

        return ans
